(function(){'use strict';const $=id=>document.getElementById(id),D=NEURO_CONTENT,P=PlatformModel,{n,download}=PlatformUI;let state=P.emptyPractice(),writable=true,cleanup=()=>{},current=null;
 try{const raw=localStorage.getItem(P.PRACTICE);if(raw)state=P.cleanPractice(JSON.parse(raw));}catch{writable=false;$('neuroStorage').hidden=false;$('neuroStorage').textContent='Не удалось прочитать сохранение. Исходные данные не изменены; новые ответы доступны в памяти этой вкладки. Скачайте их перед закрытием.';}
 function saveRecord(key,record){state.cases[key]=record;try{if(writable){const raw=localStorage.getItem(P.PRACTICE),latest=raw?P.cleanPractice(JSON.parse(raw)):P.emptyPractice();latest.cases[key]=record;state=latest;localStorage.setItem(P.PRACTICE,JSON.stringify(state));}}catch{writable=false;$('neuroStorage').hidden=false;$('neuroStorage').textContent='Запись в браузер недоступна. Скачайте текущий прогресс перед закрытием.';}}
 function svg(tag,attrs={},text){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;return e;}
 function diagram(view,label){const e=svg('svg',{viewBox:'0 0 640 290',role:'img','aria-label':label});view.append(e);return e;}
 function line(s,x1,y1,x2,y2,color='#285545',width=3){s.append(svg('line',{x1,y1,x2,y2,stroke:color,'stroke-width':width}));}
 function label(s,x,y,t){s.append(svg('text',{x,y,class:'neuro-figure-text'},t));}
 function range(box,title,min,max,value,step,unit,change){const l=n('label',undefined,'neuro-control'),head=n('span',title),input=n('input'),output=n('output',value+' '+unit,'neuro-value');input.type='range';input.setAttribute('aria-label',title);input.min=min;input.max=max;input.step=step;input.value=value;input.oninput=()=>{output.textContent=input.value+' '+unit;change(Number(input.value));};l.append(head,input,output);box.append(l);return{input,set(v){input.value=v;output.textContent=input.value+' '+unit;}};}
 function select(box,title,items,value,change){const l=n('label',undefined,'neuro-control'),s=n('select');l.append(n('span',title));for(const[id,t]of items){const o=n('option',t);o.value=id;s.append(o);}s.setAttribute('aria-label',title);s.value=value;s.onchange=()=>change(s.value);l.append(s);box.append(l);return s;}
 function check(box,title,value,change){const l=n('label'),input=n('input');input.type='checkbox';input.checked=value;input.onchange=()=>change(input.checked);l.append(input,document.createTextNode(' '+title));box.append(l);return{input};}
 function readout(box){const d=n('div',undefined,'neuro-readout');d.setAttribute('aria-live','polite');box.append(d);return d;}
 const H={n,svg,range,select,check,readout,diagram,line,label};
 const renderers={plasticity:(v,c)=>SystemsLab.mount('plasticity',v,c,H),astrocyte:(v,c)=>SystemsLab.mount('astrocyte',v,c,H),basal:(v,c)=>SystemsLab.mount('basal',v,c,H),neuron:(v,c)=>NeuroMorph.mount(v,c,H),atlas:(v,c)=>BrainAtlas.mount(v,c,H)};
 for(const id of ['synapse','action','receptor','transmitter','myelin','circuit','pharmacology','pathology'])renderers[id]=(v,c)=>NeuroSim.mount(id,v,c,H);
 function renderQuestions(module){const box=$('neuroQuestions'),key='neuro-'+module.id,record=state.cases[key]||{next:[],revealed:[]};record.next||=[];record.revealed||=[];box.replaceChildren();for(const[qindex,q]of D.quiz[module.id].entries()){const qid='q'+qindex,row=n('section',undefined,'platform-card neuro-question'),f=n('fieldset'),legend=n('legend',(qindex+1)+'. '+q.prompt);f.append(legend);const chosen=record.next.find(x=>x.startsWith(qid+':'))?.split(':')[1],checked=record.revealed.includes(qid);for(let j=0;j<4;j++){const index=(j+D.modules.indexOf(module)+qindex)%4,l=n('label'),input=n('input');input.type='radio';input.name=key+'-'+qid;input.value=index;input.checked=chosen===String(index);input.disabled=checked;input.onchange=()=>{record.next=record.next.filter(x=>!x.startsWith(qid+':'));record.next.push(qid+':'+index);saveRecord(key,record);};l.append(input,document.createTextNode(' '+q.answers[index]));f.append(l);}row.append(f);const b=n('button','Проверить','primary');b.type='button';b.hidden=checked;b.onclick=()=>{if(!record.next.some(x=>x.startsWith(qid+':'))){$('neuroStatus').textContent='Сначала выберите ответ на вопрос '+(qindex+1)+'.';return;}record.revealed.push(qid);saveRecord(key,record);$('neuroStatus').textContent='Ответ сохранён. Разберите объяснение и вернитесь к модели.';renderQuestions(module);};row.append(b);if(checked){const correct=chosen==='0',fb=n('div',undefined,'neuro-feedback'+(correct?'':' neuro-wrong'));fb.append(n('strong',correct?'Верно.':'Сопоставьте с моделью.'),n('p',(correct?'':'Ответ: '+q.answers[0]+'. ')+q.why));row.append(fb);}box.append(row);}}
 function render(){cleanup();cleanup=()=>{};let hash;try{hash=decodeURIComponent(location.hash.slice(1));}catch{hash='';}const module=D.modules.find(m=>m.id===hash||m.name.toLowerCase()===hash.toLowerCase());current=module||null;$('neuroMenu').replaceChildren();for(const[i,m]of D.modules.entries()){const a=n('a',(i+1)+'. '+m.name);a.href='#'+m.id;if(m===module)a.setAttribute('aria-current','page');$('neuroMenu').append(a);}$('neuroOverview').hidden=!!module;$('neuroModule').hidden=!module;$('neuroStatus').textContent='';if(!module){const cards=n('div',undefined,'neuro-index');for(const[i,m]of D.modules.entries()){const a=n('a',undefined,'platform-card');a.href='#'+m.id;a.append(n('b',String(i+1).padStart(2,'0')+' / '+m.name),n('h2',m.title),n('p',m.subtitle),n('small','Открыть модель и три задания →'));cards.append(a);}$('neuroOverview').replaceChildren(cards);return;}$('neuroNumber').textContent=module.name+' · '+(D.modules.indexOf(module)+1)+' / '+D.modules.length;$('neuroTitle').textContent=module.title;$('neuroGoal').textContent=module.goal;$('neuroLimit').textContent=module.note;const view=n('div',undefined,'neuro-view'),controls=n('div',undefined,'neuro-controls');$('neuroExperiment').replaceChildren(view,controls);cleanup=renderers[module.id](view,controls)||(()=>{});renderQuestions(module);const sources=$('neuroSources');sources.replaceChildren(n('h3','Источники и границы модели'),n('p','Открытые учебные источники; схемы и задания авторские. Purves по ссылке NCBI — 2-е издание (2001), не 7-е. Дата проверки ссылок: 27.10.2026.'));for(const key of module.sources){const [title,url]=D.sources[key],a=n('a',title);a.href=url;a.target='_blank';a.rel='noopener';sources.append(a);}$('neuroAdjacent').replaceChildren();const index=D.modules.indexOf(module);for(const i of[index-1,index+1])if(D.modules[i]){const a=n('a',(i<index?'← ':'')+D.modules[i].name+(i>index?' →':''));a.href='#'+D.modules[i].id;$('neuroAdjacent').append(a);}document.title=module.name+' · Нейронаука';}
 $('neuroReset').onclick=()=>{if(!current)return;saveRecord('neuro-'+current.id,{next:[],revealed:[]});renderQuestions(current);$('neuroStatus').textContent='Задания текущего модуля сброшены.';};$('neuroExport').onclick=()=>download('psycholibrary-practice-backup.json',{format:'psycholibrary-practice-backup',schemaVersion:1,state});window.addEventListener('hashchange',render);window.addEventListener('pagehide',()=>cleanup());window.addEventListener('storage',e=>{if(e.key!==P.PRACTICE)return;try{state=e.newValue?P.cleanPractice(JSON.parse(e.newValue)):P.emptyPractice();if(current)renderQuestions(current);}catch{$('neuroStatus').textContent='Другая вкладка изменила сохранение несовместимым образом. Скачайте текущие данные.';}});render();
})();
